import { ClassRecord } from "./types";

/**
 * Stand-in for a `CatalogClassModel.find(...)` MongoDB round-trip -- the
 * source of truth for class records, reached only when `catalogCache`
 * doesn't have what's needed. It's slower than the in-memory cache (it
 * models a real network/DB hop), so it should be used as a fallback, not a
 * primary path.
 *
 * It is instrumented with a call counter and a call-args log so tests can
 * assert not just that results are correct, but that this function is
 * invoked as rarely, and as narrowly, as possible: zero times when every
 * requested id is already cached, and exactly once -- passed only the
 * missing ids, not the full requested set -- when there's a genuine miss.
 */
const DB_RECORDS: Record<string, ClassRecord> = {
  "COMPSCI-61A-001": {
    classId: "COMPSCI-61A-001",
    subject: "COMPSCI",
    courseNumber: "61A",
    section: "001",
    title: "The Structure and Interpretation of Computer Programs",
    units: 4,
    instructor: "J. DeNero",
  },
  "COMPSCI-61A-002": {
    classId: "COMPSCI-61A-002",
    subject: "COMPSCI",
    courseNumber: "61A",
    section: "002",
    title: "The Structure and Interpretation of Computer Programs",
    units: 4,
    instructor: "J. DeNero",
  },
  "COMPSCI-10-001": {
    classId: "COMPSCI-10-001",
    subject: "COMPSCI",
    courseNumber: "10",
    section: "001",
    title: "The Beauty and Joy of Computing",
    units: 4,
    instructor: "D. Garcia",
  },
  "COMPSCI-70-001": {
    classId: "COMPSCI-70-001",
    subject: "COMPSCI",
    courseNumber: "70",
    section: "001",
    title: "Discrete Mathematics and Probability Theory",
    units: 4,
    instructor: "S. Rao",
  },
  "COMPSCI-169-001": {
    classId: "COMPSCI-169-001",
    subject: "COMPSCI",
    courseNumber: "169",
    section: "001",
    title: "Software Engineering",
    units: 4,
    instructor: "A. Fox",
  },
  // In the DB (source of truth) but NOT in catalogCache -- the genuine
  // cache-miss case.
  "STAT-134-001": {
    classId: "STAT-134-001",
    subject: "STAT",
    courseNumber: "134",
    section: "001",
    title: "Concepts of Probability",
    units: 4,
    instructor: "A. Bandeira",
  },
  // Note: "COMPSCI-999-001" is deliberately absent here too -- it doesn't
  // exist in the DB either, modeling a stale semantic index entry.
};

let callCount = 0;
const callArgs: string[][] = [];

export async function dbLookup(ids: string[]): Promise<ClassRecord[]> {
  callCount += 1;
  callArgs.push([...ids]);
  return ids.map((id) => DB_RECORDS[id]).filter((r): r is ClassRecord => Boolean(r));
}

/** Test helper: how many times has dbLookup been invoked since the last reset? */
export function getDbLookupCallCount(): number {
  return callCount;
}

/** Test helper: the exact `ids` array passed on each dbLookup call, in order. */
export function getDbLookupCallArgs(): string[][] {
  return callArgs;
}

/** Test helper: reset instrumentation between tests. */
export function resetDbLookupInstrumentation(): void {
  callCount = 0;
  callArgs.length = 0;
}
